import React, { useEffect, useState } from "react";
import axios from "axios";
import { useNavigate } from "react-router-dom";

function List() {
  const [data, setData] = useState([]);
  const navigate = useNavigate();

  useEffect(() => {
    axios.get(
      "https://backend.jotish.in/backend_dev/gettabledata.php"
    )
    .then(res => {
      console.log(res.data);
      // ✅ Correct path to array
      setData(res.data.TABLE_DATA.data);
    })
    .catch(err => {
      console.error(err);
    });
  }, []);

  return (
    <div>
      <h2>Employee List</h2>

      <button onClick={() => navigate("/chart")}>
        View Salary Chart
      </button>

      <table border="1">
        <thead>
          <tr>
            <th>Name</th>
            <th>City</th>
            <th>Salary</th>
          </tr>
        </thead>

        <tbody>
          {Array.isArray(data) &&
            data.map((item, index) => (
              <tr
                key={index}
                onClick={() =>
                  navigate(`/details/${index}`, { state: item })
                }
              >
                {/* item is an ARRAY */}
                <td>{item[0]}</td>  {/* Name */}
                <td>{item[2]}</td>  {/* City */}
                <td>{item[5]}</td>  {/* Salary */}
              </tr>
            ))}
        </tbody>
      </table>
    </div>
  );
}

export default List;
